const { Client } = require('pg');

const client = new Client({
  host: 'db',
  port: 5432,
  database: 'tip',
  user: 'user',
  password: 'password'
});

await client.connect();

try {
  const documentId = $input.document_id || $input.first().json.document_id;

  if (!documentId) {
    return { error: 'document_id is required' };
  }

  const result = await client.query(
    "SELECT get_document_full_text($1) as full_text",
    [documentId]
  );

  await client.end();

  if (result.rows.length > 0) {
    return {
      document_id: documentId,
      full_text: result.rows[0].full_text || 'No content found for this document'
    };
  } else {
    return {
      document_id: documentId,
      full_text: 'Document not found'
    };
  }
} catch (error) {
  await client.end();
  return { error: error.message };
}

const { Client } = require('pg');

const client = new Client({
  host: 'db',
  port: 5432,
  database: 'tip',
  user: 'user',
  password: 'password'
});

await client.connect();

try {
  const sqlQuery = $input.sql_query || $input.first().json.sql_query;

  if (!sqlQuery) {
    return { error: 'sql_query is required' };
  }

  // Security: Only allow SELECT queries
  if (!sqlQuery.trim().toLowerCase().startsWith('select')) {
    return { error: 'Only SELECT queries are allowed' };
  }

  const result = await client.query(sqlQuery);

  await client.end();

  return {
    query: sqlQuery,
    row_count: result.rows.length,
    results: result.rows
  };
} catch (error) {
  await client.end();
  return { error: error.message, query: sqlQuery };
}
